def table(df,cols,labels=None):
 d=df[cols].copy().rename(columns=labels or {})
 for c in d:
  if pd.api.types.is_float_dtype(d[c]):d[c]=d[c].map(lambda x:"—" if pd.isna(x) else f"{x:.4f}")
 names=list(d.columns); lines=["| "+" | ".join(names)+" |","|"+"|".join(["---"]*len(names))+"|"]
 lines += ["| "+" | ".join(str(v) for v in row)+" |" for row in d.itertuples(index=False,name=None)]
 return "\n".join(lines)
